import java.io.*;

public class e {
    static final long MOD = 998244353;
    static final long INV2 = (MOD + 1) / 2;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        long n = fs.nextLong();
        long m = fs.nextLong();
        long L = fs.nextLong();
        long R = fs.nextLong();

        long h = R - L;
        long even, odd;
        if (h % 2 == 1) {
            long d = (h + 1) / 2;
            even = d;
            odd = d;
        } else {
            long d = h / 2;
            even = d;
            odd = d;
            if (L % 2 == 1) odd++;
            else even++;
        }

        long exp = n * m;
        if (exp < 0) {
            System.out.println(1);
            return;
        }

        long sum = (even + odd) % MOD;
        long diff = ((even - odd) % MOD + MOD) % MOD;
        long sumPow = modPow(sum, exp);
        long diffPow = modPow(diff, exp);

        long ans;
        if (exp % 2 == 1) {
            ans = sumPow;
        } else {
            ans = (sumPow + diffPow) % MOD * INV2 % MOD;
        }
        System.out.println(ans);
    }

    static long modPow(long base, long e) {
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) res = res * base % MOD;
            base = base * base % MOD;
            e >>= 1;
        }
        return res;
    }

    static class FastScanner {
        private final BufferedInputStream in = new BufferedInputStream(System.in);

        private int read() throws IOException {
            return in.read();
        }

        public long nextLong() throws IOException {
            int x = read();
            while (x != -1 && !(x >= '0' && x <= '9') && x != '-') {
                x = read();
            }
            if (x == -1) return 0;
            boolean neg = false;
            if (x == '-') {
                neg = true;
                x = read();
            }
            long res = 0;
            while (x >= '0' && x <= '9') {
                res = res * 10 + (x - '0');
                x = read();
            }
            return neg ? -res : res;
        }
    }
}
